PRAGMA foreign_keys=ON;
CREATE TABLE hackathons(id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE',policy TEXT NOT NULL CHECK(json_valid(policy)),taxonomy TEXT NOT NULL CHECK(json_valid(taxonomy)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO hackathons(id,name,policy,taxonomy) VALUES('initial','Hackathon','{}','[]');
ALTER TABLE teams ADD COLUMN hackathon_id TEXT NOT NULL DEFAULT 'initial' REFERENCES hackathons(id);
ALTER TABLE teams ADD COLUMN status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('PENDING','ACTIVE','WITHDRAWN','DISQUALIFIED','COMPLETED'));
ALTER TABLE teams ADD COLUMN metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata));
ALTER TABLE teams ADD COLUMN registration_source TEXT NOT NULL DEFAULT 'legacy-manual';
ALTER TABLE teams ADD COLUMN created_at TEXT;
ALTER TABLE teams ADD COLUMN updated_at TEXT;
CREATE TABLE team_members(id TEXT PRIMARY KEY,team_id TEXT NOT NULL REFERENCES teams(id),hackathon_id TEXT NOT NULL REFERENCES hackathons(id),github_id INTEGER NOT NULL,github_login TEXT NOT NULL,display_name TEXT NOT NULL,email TEXT,external_id TEXT,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,removed_at TEXT);
CREATE UNIQUE INDEX one_active_team_per_github_identity ON team_members(hackathon_id,github_id) WHERE active=1;
CREATE INDEX members_team ON team_members(team_id,active);
CREATE TABLE team_repositories(team_id TEXT NOT NULL REFERENCES teams(id),repository_id INTEGER NOT NULL REFERENCES github_repositories(id),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,actor TEXT NOT NULL,PRIMARY KEY(team_id,repository_id));
CREATE TABLE github_issues(repository_id INTEGER NOT NULL REFERENCES github_repositories(id),number INTEGER NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,github_state TEXT NOT NULL CHECK(github_state IN('open','closed')),author_id INTEGER NOT NULL,author_login TEXT NOT NULL,reporter_team_id TEXT REFERENCES teams(id),source TEXT NOT NULL CHECK(source IN('PARTICIPANT','UNKNOWN','ORGANIZER')),labels TEXT NOT NULL CHECK(json_valid(labels)),classification TEXT NOT NULL CHECK(json_valid(classification)),overrides TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(overrides)),review_status TEXT NOT NULL DEFAULT 'NEEDS_TRIAGE' CHECK(review_status IN('NEEDS_TRIAGE','APPROVED','REJECTED','DUPLICATE','NEEDS_INFORMATION','RECOGNIZED')),official INTEGER NOT NULL DEFAULT 0,canonical_number INTEGER,recognition TEXT,github_updated_at TEXT NOT NULL,snapshot_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(repository_id,number));
CREATE INDEX issues_review ON github_issues(review_status,repository_id);
CREATE TABLE challenge_definitions(repository_id INTEGER NOT NULL,issue_number INTEGER NOT NULL,current_contract_hash TEXT NOT NULL REFERENCES contracts(hash),ownership TEXT NOT NULL CHECK(ownership IN('EXCLUSIVE','SHARED')),claimable INTEGER NOT NULL DEFAULT 0,capacity INTEGER NOT NULL DEFAULT 1 CHECK(capacity BETWEEN 1 AND 1000),availability TEXT NOT NULL DEFAULT 'AVAILABLE' CHECK(availability IN('AVAILABLE','RESERVED','BLOCKED','ARCHIVED')),eligible_teams TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(eligible_teams)),evaluation_kind TEXT NOT NULL CHECK(evaluation_kind IN('MANDATORY','OPTIONAL','BONUS','NOT_SCORED')),PRIMARY KEY(repository_id,issue_number),FOREIGN KEY(repository_id,issue_number) REFERENCES github_issues(repository_id,number));
CREATE TABLE challenge_versions(contract_hash TEXT PRIMARY KEY REFERENCES contracts(hash),repository_id INTEGER NOT NULL,issue_number INTEGER NOT NULL,definition_snapshot TEXT NOT NULL CHECK(json_valid(definition_snapshot)),actor TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(repository_id,issue_number) REFERENCES github_issues(repository_id,number));
CREATE TABLE issue_assignments(id TEXT PRIMARY KEY,team_id TEXT NOT NULL REFERENCES teams(id),repository_id INTEGER NOT NULL,issue_number INTEGER NOT NULL,contract_hash TEXT NOT NULL REFERENCES contracts(hash),exclusive INTEGER NOT NULL CHECK(exclusive IN(0,1)),source TEXT NOT NULL CHECK(source IN('ORGANIZER','CLAIM','IMPORT')),status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','RESERVED','REVOKED','EXPIRED')),progress TEXT NOT NULL DEFAULT 'ASSIGNED' CHECK(progress IN('ASSIGNED','IN_PROGRESS','EVALUATING','NEEDS_REVIEW','COMPLETED','BLOCKED')),policy_snapshot TEXT NOT NULL CHECK(json_valid(policy_snapshot)),actor TEXT NOT NULL,expires_at TEXT,assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,revoked_at TEXT,FOREIGN KEY(repository_id,issue_number) REFERENCES github_issues(repository_id,number));
CREATE UNIQUE INDEX exclusive_issue_owner ON issue_assignments(repository_id,issue_number) WHERE exclusive=1 AND status IN('ACTIVE','RESERVED');
CREATE UNIQUE INDEX one_live_team_issue_assignment ON issue_assignments(team_id,repository_id,issue_number) WHERE status IN('ACTIVE','RESERVED');
CREATE INDEX assigned_team ON issue_assignments(team_id,status);
CREATE TABLE management_inbox(id TEXT PRIMARY KEY,payload_hash TEXT NOT NULL,event TEXT NOT NULL,document TEXT NOT NULL CHECK(json_valid(document)),status TEXT NOT NULL DEFAULT 'PENDING',attempts INTEGER NOT NULL DEFAULT 0,lease_until INTEGER,last_error TEXT,received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT);
CREATE TABLE github_sync_actions(id TEXT PRIMARY KEY,repository_id INTEGER NOT NULL REFERENCES github_repositories(id),issue_number INTEGER NOT NULL,kind TEXT NOT NULL,document TEXT NOT NULL CHECK(json_valid(document)),status TEXT NOT NULL DEFAULT 'PENDING',attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT);
ALTER TABLE assignments ADD COLUMN resolution_snapshot TEXT CHECK(resolution_snapshot IS NULL OR json_valid(resolution_snapshot));
CREATE TABLE submissions_v2(repository_id INTEGER NOT NULL REFERENCES repositories(id),pr_number INTEGER NOT NULL,id TEXT NOT NULL UNIQUE DEFAULT (lower(hex(randomblob(16)))),head_sha TEXT NOT NULL,latest_run_id TEXT,github_updated_at TEXT NOT NULL,closed INTEGER NOT NULL DEFAULT 0,team_id TEXT REFERENCES teams(id),author_id INTEGER,author_login TEXT,base_sha TEXT,issue_numbers TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(issue_numbers)),assignment_ids TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(assignment_ids)),status TEXT NOT NULL DEFAULT 'NEEDS_TEAM_MAPPING',mapping_reason TEXT NOT NULL DEFAULT '',override TEXT CHECK(override IS NULL OR json_valid(override)),pr_snapshot TEXT CHECK(pr_snapshot IS NULL OR json_valid(pr_snapshot)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(repository_id,pr_number));
INSERT INTO submissions_v2(repository_id,pr_number,id,head_sha,latest_run_id,github_updated_at,closed,team_id,issue_numbers,base_sha,status,mapping_reason) SELECT s.repository_id,s.pr_number,CAST(s.repository_id AS TEXT)||':'||CAST(s.pr_number AS TEXT),s.head_sha,s.latest_run_id,s.github_updated_at,s.closed,a.team_id,COALESCE(a.issue_numbers,'[]'),e.baseline_sha,'VALID','Historical explicit organizer assignment' FROM submissions s LEFT JOIN assignments a ON a.repository_id=s.repository_id AND a.pr_number=s.pr_number LEFT JOIN evaluations e ON e.id=s.latest_run_id;
DROP TABLE submissions;
ALTER TABLE submissions_v2 RENAME TO submissions;
CREATE INDEX submissions_team ON submissions(team_id,status,github_updated_at DESC);
-- Selected repositories may have unmapped submissions before their first contract.
-- A neutral repository row is registered by synchronization before submission intake.
CREATE TABLE completion_decisions(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,assignment_id TEXT NOT NULL REFERENCES issue_assignments(id),run_id TEXT REFERENCES evaluations(id),decision TEXT NOT NULL CHECK(decision IN('ACCEPTED','CHANGES_REQUESTED','REOPENED')),reason TEXT NOT NULL,actor TEXT NOT NULL,evidence_snapshot TEXT NOT NULL CHECK(json_valid(evidence_snapshot)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE audit ADD COLUMN actor TEXT NOT NULL DEFAULT 'system';
ALTER TABLE audit ADD COLUMN changes TEXT CHECK(changes IS NULL OR json_valid(changes));
CREATE TRIGGER immutable_challenge_versions BEFORE UPDATE ON challenge_versions BEGIN SELECT RAISE(ABORT,'Challenge versions are immutable'); END;
CREATE TRIGGER immutable_issue_assignment_inputs BEFORE UPDATE OF team_id,repository_id,issue_number,contract_hash,exclusive,source,policy_snapshot,actor ON issue_assignments BEGIN SELECT RAISE(ABORT,'Assignment inputs are immutable'); END;
CREATE TRIGGER immutable_completion_decisions BEFORE UPDATE ON completion_decisions BEGIN SELECT RAISE(ABORT,'Completion decisions are immutable'); END;

ALTER TABLE github_sync_actions ADD COLUMN lease_until INTEGER;
ALTER TABLE submissions ADD COLUMN resolution_revision INTEGER NOT NULL DEFAULT 0;
